mapper.select:
select extract_id, document_id, material_type, model_name, prompt_version, ai_json, final_json, status,
       create_by, create_time, update_by, update_time, remark
from 
where document_id = #{documentId}
  and extract_id = #{extractId}
limit 1

mapper.update:
update 
set final_json = #{finalJson}, status = #{status}, update_by = #{updateBy}, update_time = #{updateTime}
where document_id = #{documentId}
  and extract_id = #{extractId}
